    def get_hls_url(self, rtsp_url):
        m = re.search(r"rtsp://(strm\d\.spatic\.go\.kr):1935/live/(\d+)\.stream", rtsp_url)
        if m:
            return f"https://{m.group(1)}/live/{m.group(2)}.stream/playlist.m3u8"
        return None

    def collect(self):
        print(f"Collecting SPATIC (Seoul Police) data ({len(self.DATA)} items)...")
        results = []
        for item in self.DATA:
            hls_url = self.get_hls_url(item["rtsp"])
            if hls_url:
                results.append({
                    "id": f"SPATIC_{item['id']}",
                    "name": f"[SPATIC] {item['name']}",
                    "lat": item["lat"],
                    "lng": item["lon"],
                    "url": hls_url,
                    "source": "SPATIC",
                    "status": "active",
                    "address": f"서울특별시 {item['name']}",
                    "backup_urls": []
                })
        print(f"Successfully normalized {len(results)} SPATIC streams.")
        return results
